class HTTPBase(SecurityBase):
    def __init__(
        self,
        *,
        scheme: str,
        scheme_name: Optional[str] = None,
        description: Optional[str] = None,
        auto_error: bool = True,
        not_authenticated_status_code: Optional[int] = None,
    ):
        self.model = HTTPBaseModel(scheme=scheme, description=description)
        self.scheme = scheme
        self.scheme_name = scheme_name or self.__class__.__name__
        self.auto_error = auto_error
        self.not_authenticated_status_code = not_authenticated_status_code

    def format_www_authenticate_header_value(self) -> str:
        return self.scheme.capitalize()

    async def __call__(
        self, request: Request
    ) -> Optional[HTTPAuthorizationCredentials]:
        authorization = request.headers.get("Authorization")
        scheme, credentials = get_authorization_scheme_param(authorization)
        if not (authorization and scheme and credentials):
            if self.auto_error:
                status_code = self.not_authenticated_status_code or HTTP_401_UNAUTHORIZED
                headers = {"WWW-Authenticate": self.format_www_authenticate_header_value()}
                raise HTTPException(
                    status_code=status_code, detail="Not authenticated", headers=headers
                )
            else:
                return None
        if scheme.lower() != self.scheme.lower():
            if self.auto_error:
                # For invalid scheme, the problem statement says:
                # "For HTTPBearer and OpenIdConnect: ... The default status code for not providing the authorization parameter was changed from 403 to 401."
                # It doesn't explicitly say what to do for invalid scheme, but usually it's also 401 or 403.
                # In the current implementation of HTTPBearer, it's 403.
                # Let's see if we should change it to 401 too.
                # "The suggested implementation will be in line with the current implementations of OAuth2PasswordBearer and OAuth2AuthorizationCodeBearer."
                # Let's check those.
                raise HTTPException(
                    status_code=HTTP_403_FORBIDDEN,
                    detail="Invalid authentication credentials",
                )
            else:
                return None
        return HTTPAuthorizationCredentials(scheme=scheme, credentials=credentials)
```

